/// Extract the lowercase host of an `http`/`https` URL, or `None` if the URL
/// is malformed or uses some other scheme. Deliberately conservative: anything
/// ambiguous is rejected rather than guessed at.
fn host_of(url: &str) -> Option<String> {
    if url
        .chars()
        .any(|c| c.is_whitespace() || c.is_control() || c == '\\')
    {
        return None;
    }
    let lower = url.to_ascii_lowercase();
    let rest = lower
        .strip_prefix("https://")
        .or_else(|| lower.strip_prefix("http://"))?;
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    // Userinfo is not something a feed URL needs; refuse rather than parse it.
    if authority.contains('@') {
        return None;
    }
    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            &authority[..i]
        }
        None => authority,
    };
    let host = host.strip_suffix('.').unwrap_or(host);
    if host.is_empty()
        || !host
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'.')
    {
        return None;
    }
    Some(host.to_string())
}

/// Encode the input as JSON: `{"urls":["...", ...]}`.
fn encode_input(input: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in input.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        push_json_string(&mut out, url);
    }
    out.push_str("]}");
    out
}

fn push_json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
